function normalize(name) {
  return String(name ?? '').normalize('NFKD').toLowerCase().replace(/\p{M}/gu,'')
    .replace(/[łøß]/g, character => ({ ł:'l',ø:'o',ß:'ss' })[character])
    .replace(/\s*\([a-z]{3}\)\s*$/,'').replace(/&/g,' and ')
    .replace(/[^a-z0-9]+/g,' ').replace(/\butd\b/g,'united').trim();
}

function bareName(name) {
  const parts = normalize(name).split(' ');
  const affix = /^(ac|afc|as|bc|ca|cd|cf|fc|fk|kv|pae|rc|rcd|sc|sco|sk|ss|sv|tsg|ud|us|vfb|vfl)$/;
  while (parts.length > 1 && affix.test(parts[0])) parts.shift();
  while (parts.length > 1 && affix.test(parts.at(-1))) parts.pop();
  return parts.join(' ');
}

function buildIndex(rows) {
  const result = new Map();
  for (const [primary,secondary,names] of rows) {
    const kit = Object.freeze({primary:'#' + primary,secondary:'#' + secondary,source:'Team colours'});
    for (const name of names.split('|')) {
      result.set(normalize(name),kit);
      if (!result.has(bareName(name))) result.set(bareName(name),kit);
    }
  }
  return result;
}

const clubs = buildIndex(clubRows);
const countries = buildIndex(countryRows);

export function getClubKit(team) {
  const name = typeof team === 'string' ? team : team?.name;
  if (!name) return null;
  const national = team?.kind === 'national' || team?.national === true;
  if (national) return countries.get(normalize(name)) ?? null;
  const club = clubs.get(normalize(name)) ?? clubs.get(bareName(name));
  if (club) return club;
  return countries.get(normalize(name)) ?? null;
}
